#!/usr/bin/env python3
import json
import os
import sys

def parse_env_file(file_path):
    """Parse .env file and return dict of key-value pairs"""
    env_dict = {}

    try:
        with open(file_path, 'r') as f:
            for line in f:
                line = line.strip()
                # Skip empty lines and comments
                if not line or line.startswith('#'):
                    continue

                # Split on first '='
                if '=' in line:
                    key, value = line.split('=', 1)
                    env_dict[key.strip()] = value.strip()
    except Exception as e:
        print(f"Error parsing env file: {e}")
        sys.exit(1)

    return env_dict

def main():
    if len(sys.argv) != 2:
        print("Usage: python3 convert_env_to_json.py <env_file_path>")
        sys.exit(1)

    env_file = sys.argv[1]
    if not os.path.exists(env_file):
        print(f"File not found: {env_file}")
        sys.exit(1)

    env_dict = parse_env_file(env_file)

    # Output as JSON
    print(json.dumps(env_dict, indent=2))

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import json
import os

def parse_env_file(file_path):
    env_dict = {}
    with open(file_path, 'r') as f:
        for line in f:
            line = line.strip()
            # Skip empty lines and comments
            if not line or line.startswith('#'):
                continue
            # Parse key=value pairs
            if '=' in line:
                key, value = line.split('=', 1)
                env_dict[key.strip()] = value.strip()
    return env_dict

# Read .env.test and convert to JSON
env_data = parse_env_file('.env.test')
print(json.dumps(env_data))

